        if msg.get("role") != "user":
            result.append(msg)
            continue
        content = msg.get("content", "")
        if not content:
            result.append(msg)
            continue
        original_before_pass = content
        cur_pass_mods = []
        if _content_contains(content, _SKILLS_MARKER):
            new_content = _strip_system_reminder(content, _SKILLS_MARKER)
